package com.rsd.middle.drawdown;

import com.rsd.middle.credit.CreditLimitRepository;
import com.rsd.middle.credit.LimitService;
import com.rsd.middle.credit.ProductConfigRepository;
import com.rsd.middle.credit.ProductConfig;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import java.math.BigDecimal;
import java.util.List;
import java.util.Map;

/** 中台渠道接入 API（阶段 2 提款部分）。契约见 docs/接口契约-阶段2.md §4。 */
@RestController
@RequestMapping("/middle/api/v1/drawdowns")
public class DrawdownController {

    private final DrawdownService drawdownService;
    private final LimitService limitService;
    private final ProductConfigRepository productRepo;
    private final CreditLimitRepository creditRepo;

    public DrawdownController(DrawdownService drawdownService, LimitService limitService,
                              ProductConfigRepository productRepo, CreditLimitRepository creditRepo) {
        this.drawdownService = drawdownService;
        this.limitService = limitService;
        this.productRepo = productRepo;
        this.creditRepo = creditRepo;
    }

    public record QuoteRequest(String creditId, String productId, BigDecimal amount,
                               Integer termMonths, String repaymentMode, String firstRepaymentDate) {
    }

    public record ApplyRequest(String quoteNo, String payeeName, String payeeAccount, String purpose) {
    }

    @GetMapping("/options")
    public Map<String, Object> options(@RequestParam String creditId) {
        limitService.get(creditId);
        List<Map<String, Object>> products = productRepo.findAll().stream()
                .map(p -> Map.<String, Object>of(
                        "productId", p.getProductId(),
                        "productName", p.getProductName(),
                        "minAmount", p.getMinAmount(),
                        "maxAmount", p.getMaxAmount(),
                        "terms", p.termList(),
                        "repaymentModes", p.repaymentModeList(),
                        // 多层口径：各约束层余量取最小值（总授信/产品子额度/集团限额/担保覆盖）
                        "availableAmount", limitService.availableForDrawdown(creditId, p.getProductId(), p.isRequiresGuarantee())))
                .toList();
        return Map.of("creditId", creditId, "products", products);
    }

    @PostMapping("/quote")
    public Map<String, Object> quote(@RequestBody QuoteRequest request) {
        return drawdownService.quote(request.creditId(), request.productId(), request.amount(),
                request.termMonths(), request.repaymentMode(), request.firstRepaymentDate());
    }

    @PostMapping
    public Map<String, Object> apply(@RequestBody ApplyRequest request) {
        DrawdownOrder order = drawdownService.apply(request.quoteNo(), request.payeeName(),
                request.payeeAccount(), request.purpose());
        return Map.of("bizOrderNo", order.getBizOrderNo(), "status", order.getStatus().name());
    }

    @GetMapping("/{bizOrderNo}")
    public Map<String, Object> detail(@PathVariable String bizOrderNo) {
        return drawdownService.detail(bizOrderNo);
    }
}

package com.rsd.middle.compensation;

import com.rsd.middle.credit.CreditApplicationOrder;
import com.rsd.middle.credit.CreditApplicationRepository;
import com.rsd.middle.credit.CreditService;
import com.rsd.middle.drawdown.DrawdownOrder;
import com.rsd.middle.drawdown.DrawdownOrderRepository;
import com.rsd.middle.drawdown.DrawdownService;
import com.rsd.middle.repay.RepaymentOrder;
import com.rsd.middle.repay.RepaymentOrderRepository;
import com.rsd.middle.repay.RepaymentService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import java.time.Duration;
import java.time.LocalDateTime;
import java.util.List;

/**
 * 查单与补偿任务（不引入消息中间件，用定时任务收敛异步结果，见边界设计原则 6）：
 * 1. 提交失败 → 重新提交（模拟服务按 bizOrderNo 幂等）；
 * 2. 受理中超时未收到回调 → 主动查单（"回调未送达，通过查单取得结果"场景）；
 * 3. 提款入账未完成（TO_BOOK / RETRY_NEEDED）→ 重试入账，先查借据是否已 ACTIVE 防重复放款；
 * 4. 授信审批受理超时 → 查审批结论。
 */
@Component
public class CompensationTask {

    private static final Logger log = LoggerFactory.getLogger(CompensationTask.class);

    private final DrawdownOrderRepository drawdownRepo;
    private final RepaymentOrderRepository repayRepo;
    private final CreditApplicationRepository creditRepo;
    private final DrawdownService drawdownService;
    private final RepaymentService repaymentService;
    private final CreditService creditService;
    private final long paymentQueryTimeoutSeconds;
    private final int bookingRetryMax;

    public CompensationTask(DrawdownOrderRepository drawdownRepo, RepaymentOrderRepository repayRepo,
                            CreditApplicationRepository creditRepo, DrawdownService drawdownService,
                            RepaymentService repaymentService, CreditService creditService,
                            @Value("${compensation.payment-query-timeout-seconds:60}") long paymentQueryTimeoutSeconds,
                            @Value("${compensation.booking-retry-max:5}") int bookingRetryMax) {
        this.drawdownRepo = drawdownRepo;
        this.repayRepo = repayRepo;
        this.creditRepo = creditRepo;
        this.drawdownService = drawdownService;
        this.repaymentService = repaymentService;
        this.creditService = creditService;
        this.paymentQueryTimeoutSeconds = paymentQueryTimeoutSeconds;
        this.bookingRetryMax = bookingRetryMax;
    }

    @Scheduled(fixedDelayString = "${compensation.poll-interval-ms:15000}")
    public void compensate() {
        // 提款：提交失败重试
        drawdownRepo.findByPaymentStatus(DrawdownOrder.PaymentStatus.TO_SUBMIT)
                .forEach(drawdownService::submitPayment);
        // 提款：受理超时主动查单
        LocalDateTime deadline = LocalDateTime.now().minus(Duration.ofSeconds(paymentQueryTimeoutSeconds));
        List<DrawdownOrder> pendingPayments = drawdownRepo.findByPaymentStatus(DrawdownOrder.PaymentStatus.PROCESSING);
        for (DrawdownOrder order : pendingPayments) {
            if (order.getUpdatedAt() != null && order.getUpdatedAt().isBefore(deadline)) {
                log.info("提款付款超时，主动查单: {}", order.getBizOrderNo());
                drawdownService.queryAndSettle(order);
            }
        }
        // 提款：入账未完成 → 重试（含"外部已成功、中台未入账"的可恢复状态）
        for (DrawdownOrder order : drawdownRepo.findByBookingStatus(DrawdownOrder.BookingStatus.TO_BOOK)) {
            drawdownService.book(order);
        }
        for (DrawdownOrder order : drawdownRepo.findByBookingStatus(DrawdownOrder.BookingStatus.RETRY_NEEDED)) {
            if (order.getBookingRetryCount() != null && order.getBookingRetryCount() < bookingRetryMax) {
                drawdownService.book(order);
            }
        }
        // 还款：同样的三条补偿线
        repayRepo.findByDeductionStatus(RepaymentOrder.DeductionStatus.TO_SUBMIT)
                .forEach(repaymentService::submitDeduction);
        for (RepaymentOrder order : repayRepo.findByDeductionStatus(RepaymentOrder.DeductionStatus.PROCESSING)) {
            if (order.getUpdatedAt() != null && order.getUpdatedAt().isBefore(deadline)) {
                log.info("还款扣款超时，主动查单: {}", order.getBizOrderNo());
                repaymentService.queryAndSettle(order);
            }
        }
        // 扣款成功但入账未完成的还款订单（PROCESSING 且扣款已 SUCCESS）
        repayRepo.findByDeductionStatus(RepaymentOrder.DeductionStatus.SUCCESS).stream()
                .filter(order -> order.getStatus() == RepaymentOrder.Status.PROCESSING)
                .forEach(repaymentService::book);
        // 授信审批：未拿到流水号的重试提交；受理超时的查审批结论
        creditRepo.findByStatus(CreditApplicationOrder.Status.PROCESSING).forEach(order -> {
            if (order.getApprovalExtSerialNo() == null) {
                creditService.submitApproval(order);
            } else if (order.getUpdatedAt() != null && order.getUpdatedAt().isBefore(deadline)) {
                log.info("授信审批超时，主动查单: {}", order.getBizOrderNo());
                creditService.queryAndSettle(order);
            }
        });
    }
}

package com.rsd.middle.external;

import com.rsd.middle.common.BizException;
import com.rsd.middle.credit.CreditApplicationOrder;
import com.rsd.middle.credit.CreditApplicationRepository;
import com.rsd.middle.credit.CreditService;
import com.rsd.middle.drawdown.DrawdownOrder;
import com.rsd.middle.drawdown.DrawdownOrderRepository;
import com.rsd.middle.drawdown.DrawdownService;
import com.rsd.middle.repay.RepaymentOrder;
import com.rsd.middle.repay.RepaymentOrderRepository;
import com.rsd.middle.repay.RepaymentService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import java.math.BigDecimal;
import java.util.Map;

/**
 * 外部结果回调接收（模拟服务 → 中台）：付款、扣款、授信审批。
 * 幂等由各业务服务保证：终态业务单收到重复回调直接确认（DUPLICATE_CALLBACK 不改变状态）。
 * 回调成功只代表外部环节完成；提款是否成功以中台入账状态为准，授信是否生效以中台账本为准。
 */
@RestController
@RequestMapping("/middle/api/v1/callbacks")
public class ExternalResultController {

    private static final Logger log = LoggerFactory.getLogger(ExternalResultController.class);

    private final DrawdownOrderRepository drawdownRepo;
    private final RepaymentOrderRepository repayRepo;
    private final CreditApplicationRepository creditRepo;
    private final DrawdownService drawdownService;
    private final RepaymentService repaymentService;
    private final CreditService creditService;

    public ExternalResultController(DrawdownOrderRepository drawdownRepo, RepaymentOrderRepository repayRepo,
                                    CreditApplicationRepository creditRepo, DrawdownService drawdownService,
                                    RepaymentService repaymentService, CreditService creditService) {
        this.drawdownRepo = drawdownRepo;
        this.repayRepo = repayRepo;
        this.creditRepo = creditRepo;
        this.drawdownService = drawdownService;
        this.repaymentService = repaymentService;
        this.creditService = creditService;
    }

    public record ExternalResult(String type, String extSerialNo, String bizOrderNo, String result,
                                 BigDecimal approvedLimit, String finishedAt) {
    }

    @PostMapping("/external-result")
    public Map<String, Object> onExternalResult(@RequestBody ExternalResult callback) {
        log.info("收到外部结果回调: {}", callback);
        try {
            switch (callback.type()) {
                case "PAYMENT" -> {
                    DrawdownOrder order = drawdownRepo.findById(callback.bizOrderNo()).orElse(null);
                    if (order != null && callback.extSerialNo().equals(order.getExtSerialNo())) {
                        drawdownService.onPaymentResult(order, callback.result());
                    }
                }
                case "DEDUCTION" -> {
                    RepaymentOrder order = repayRepo.findById(callback.bizOrderNo()).orElse(null);
                    if (order != null && callback.extSerialNo().equals(order.getExtSerialNo())) {
                        repaymentService.onDeductionResult(order, callback.result());
                    }
                }
                case "APPROVAL" -> {
                    CreditApplicationOrder order = creditRepo.findById(callback.bizOrderNo()).orElse(null);
                    if (order != null && callback.extSerialNo().equals(order.getApprovalExtSerialNo())) {
                        creditService.onApprovalResult(order, callback.result(), callback.approvedLimit());
                    }
                }
                default -> log.warn("未知回调类型: {}", callback.type());
            }
        } catch (BizException e) {
            if (e.code != BizException.Code.DUPLICATE_CALLBACK) {
                throw e;
            }
        }
        return Map.of("received", true);
    }
}

package com.rsd.middle.fineract;

import com.rsd.middle.common.BizException;
import com.rsd.middle.common.Ids;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.Map;

/**
 * Fineract REST 适配层：中台唯一允许触 Fineract 的模块（docs/三系统边界设计.md §5）。
 * 端点与命令语义对应 Fineract 1.14.0：LoansApiResource(/v1/loans)、LoanTransactionsApiResource(/v1/loans/{id}/transactions)。
 * 审批命令本设计不需要单独调用：中台创建借据即审批放款一体（受托支付成功才登记），
 * 因此创建时直接提交为经审批口径（submittedOnDate+approvedOnDate），放款在支付确认后执行。
 */
@Component
@EnableConfigurationProperties(FineractProperties.class)
public class FineractClient {

    private static final Logger log = LoggerFactory.getLogger(FineractClient.class);

    private final FineractProperties props;
    private final RestClient http;

    public FineractClient(FineractProperties props) {
        this.props = props;
        String auth = Base64.getEncoder().encodeToString(
                (props.username() + ":" + props.password()).getBytes(StandardCharsets.UTF_8));
        this.http = RestClient.builder()
                .baseUrl(props.baseUrl())
                .defaultHeader(HttpHeaders.AUTHORIZATION, "Basic " + auth)
                .defaultHeader("Fineract-Platform-TenantId", props.tenantId())
                .defaultHeader(HttpHeaders.CONTENT_TYPE, MediaType.APPLICATION_JSON_VALUE)
                .build();
    }

    /** 中台还款方式 → Fineract amortizationType（AmortizationMethod：0=EQUAL_PRINCIPAL，1=EQUAL_INSTALLMENTS）。 */
    public static int amortizationType(String repaymentMode) {
        return switch (repaymentMode) {
            case "EQUAL_PRINCIPAL" -> 0;
            case "EQUAL_INSTALLMENTS" -> 1;
            default -> throw new BizException(BizException.Code.PRODUCT_NOT_OPEN);
        };
    }

    /** 创建借据（贷款申请）。返回 Fineract loanId。 */
    @SuppressWarnings("unchecked")
    public String createLoan(String fineractProductId, BigDecimal principal, int termMonths,
                             String repaymentMode, String firstRepaymentDate) {
        Map<String, Object> payload = Map.ofEntries(
                Map.entry("productId", Long.valueOf(fineractProductId)),
                Map.entry("principal", principal),
                Map.entry("loanTermFrequency", termMonths),
                Map.entry("loanTermFrequencyType", 2),          // 2=MONTHS（PeriodFrequencyType）
                Map.entry("repaymentEvery", 1),
                Map.entry("repaymentFrequencyType", 2),
                Map.entry("interestType", 0),                   // 0=DECLINING_BALANCE
                Map.entry("interestCalculationPeriodMethod", 1),// 1=SAME_AS_REPAYMENT_PERIOD
                Map.entry("amortizationType", amortizationType(repaymentMode)),
                Map.entry("transactionProcessingStrategyCode", "mifos-standard-strategy"),
                Map.entry("submittedOnDate", Ids.now().toLocalDate().toString()),
                Map.entry("expectedDisbursementDate", Ids.now().toLocalDate().toString()),
                Map.entry("repaymentStartDateType", 1),         // 1=DISBURSEMENT_DATE
                Map.entry("dateFormat", Ids.DATE_FMT),
                Map.entry("locale", "en"));
        Map<String, Object> resp = http.post().uri("/loans")
                .body(payload)
                .retrieve().body(Map.class);
        log.info("fineract createLoan -> {}", resp);
        return String.valueOf(resp.get("loanId"));
    }

    /** 借据当前状态（幂等判定用：放款重试前先看是否已 ACTIVE）。 */
    @SuppressWarnings("unchecked")
    public boolean isLoanActive(String loanAccountNo) {
        Map<String, Object> loan = http.get().uri("/loans/{id}", loanAccountNo).retrieve().body(Map.class);
        Map<String, Object> status = (Map<String, Object>) loan.get("status");
        return Boolean.TRUE.equals(status.get("active"));
    }

    /** 放款登记（command=disburse）。真实放款金额与放款日由此固定为借据起息依据。 */
    public void disburseLoan(String loanAccountNo, BigDecimal amount) {
        http.post().uri(uri -> uri.path("/loans/{id}").queryParam("command", "disburse").build(loanAccountNo))
                .body(Map.of("transactionAmount", amount,
                        "note", "融商贷受托支付放款",
                        "dateFormat", Ids.DATE_FMT, "locale", "en"))
                .retrieve().toBodilessEntity();
    }

    /** 试算还款计划（command=calculateLoanSchedule，不创建账户）。 */
    @SuppressWarnings("unchecked")
    public Map<String, Object> calculateLoanSchedule(String fineractProductId, BigDecimal principal, int termMonths,
                                                     String repaymentMode, String firstRepaymentDate) {
        Map<String, Object> payload = Map.of(
                "productId", Long.valueOf(fineractProductId),
                "principal", principal,
                "loanTermFrequency", termMonths,
                "loanTermFrequencyType", 2,
                "repaymentEvery", 1,
                "repaymentFrequencyType", 2,
                "interestType", 0,
                "interestCalculationPeriodMethod", 1,
                "amortizationType", amortizationType(repaymentMode),
                "transactionProcessingStrategyCode", "mifos-standard-strategy",
                "expectedDisbursementDate", Ids.now().toLocalDate().toString(),
                "repaymentStartDateType", 1,
                "dateFormat", Ids.DATE_FMT, "locale", "en",
                "command", "calculateLoanSchedule");
        return http.post().uri("/loans").body(payload).retrieve().body(Map.class);
    }

    /** 提前结清/部分还本试算（GET /loans/{id}?command=calculatePrepayment）。 */
    @SuppressWarnings("unchecked")
    public Map<String, Object> calculatePrepayment(String loanAccountNo, String today) {
        return http.get()
                .uri(uri -> uri.path("/loans/{id}").queryParam("command", "calculatePrepayment")
                        .queryParam("dateFormat", Ids.DATE_FMT).queryParam("locale", "en")
                        .build(loanAccountNo))
                .retrieve().body(Map.class);
    }

    /** 还款入账（POST /loans/{id}/transactions?command=repayment）。返回 Fineract 交易 id。 */
    @SuppressWarnings("unchecked")
    public String repayLoan(String loanAccountNo, BigDecimal amount) {
        Map<String, Object> resp = http.post()
                .uri(uri -> uri.path("/loans/{id}/transactions")
                        .queryParam("command", "repayment").build(loanAccountNo))
                .body(Map.of("transactionAmount", amount,
                        "transactionDate", Ids.now().toLocalDate().toString(),
                        "dateFormat", Ids.DATE_FMT, "locale", "en"))
                .retrieve().body(Map.class);
        return String.valueOf(resp.get("resourceId"));
    }

    /**
     * 还款分配明细：读取该笔交易的本金/利息/费用部分。
     * 依据 Fineract 还款交易响应中的 principalPortion/interestPortion/feeChargesPortion，
     * 中台只按本金部分恢复额度（利息费用不恢复）。
     */
    @SuppressWarnings("unchecked")
    public RepaymentAllocation getRepaymentAllocation(String loanAccountNo, String transactionId) {
        Map<String, Object> tx = http.get()
                .uri("/loans/{id}/transactions/{tx}", loanAccountNo, transactionId)
                .retrieve().body(Map.class);
        BigDecimal principal = toBigDecimal(tx.get("principalPortion"));
        BigDecimal interest = toBigDecimal(tx.get("interestPortion"));
        BigDecimal fees = toBigDecimal(tx.get("feeChargesPortion")).add(toBigDecimal(tx.get("penaltyChargesPortion")));
        return new RepaymentAllocation(transactionId, principal, interest, fees);
    }

    public record RepaymentAllocation(String transactionId, BigDecimal principalPortion,
                                      BigDecimal interestPortion, BigDecimal feePortion) {
    }

    private static BigDecimal toBigDecimal(Object value) {
        return value == null ? BigDecimal.ZERO : new BigDecimal(String.valueOf(value));
    }
}

package com.rsd.middle.credit;

import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 授信申请单：初次授信、提额、降额、续授信都走申请＋外部审批；冻结/解冻是运营操作不走审批。
 * 审批通过后由中台按 type 生效（INITIAL 建授信＋各层配置；DECREASE 降额保留占用）。
 */
@Entity
@Table(name = "credit_application")
public class CreditApplicationOrder {

    public enum Status { PROCESSING, APPROVED, REJECTED }

    public enum Type { INITIAL, LIMIT_INCREASE, LIMIT_DECREASE, RENEWAL }

    @Id
    private String bizOrderNo;         // CR-开头
    private String customerName;
    private Type type;
    private String targetCreditId;     // 调整类申请的目标授信；INITIAL 为空
    private BigDecimal requestedLimit;

    // 各层配置随申请提交，审批通过后一并生效
    private String groupNo;
    private String productSubLimitsJson;
    private String guaranteeOrgName;
    private BigDecimal guaranteeCoverageLimit;
    private BigDecimal guaranteeCoverageRatio;

    private Status status;
    private String approvalExtSerialNo;
    private BigDecimal approvedLimit;  // 模拟审批返回的批准额度
    private String createdCreditId;    // INITIAL 生效后的授信号
    private LocalDateTime createdAt;
    private LocalDateTime updatedAt;

    public boolean terminal() {
        return status == Status.APPROVED || status == Status.REJECTED;
    }

