package com.rsd.middle.credit;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.rsd.middle.common.BizException;
import com.rsd.middle.common.Ids;
import com.rsd.middle.external.SimulatorClient;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.List;
import java.util.Map;

/**
 * 授信申请与调整编排：申请单 → 模拟审批（回调/查单）→ 中台生效。
 * 审批结果只是数据；额度生效、降额后保留占用、冻结状态全部由中台账本决定（边界设计 §6 判例）。
 * 冻结/解冻是运营操作，不走审批。
 */
@Service
public class CreditService {

    private static final Logger log = LoggerFactory.getLogger(CreditService.class);

    private final CreditApplicationRepository applicationRepo;
    private final CreditLimitRepository limitRepo;
    private final LimitService limitService;
    private final ProductSubLimitRepository subLimitRepo;
    private final GroupMemberRepository groupMemberRepo;
    private final GuaranteeCoverageRepository coverageRepo;
    private final SimulatorClient simulator;
    private final ObjectMapper objectMapper;

    public CreditService(CreditApplicationRepository applicationRepo, CreditLimitRepository limitRepo,
                         LimitService limitService, ProductSubLimitRepository subLimitRepo,
                         GroupMemberRepository groupMemberRepo, GuaranteeCoverageRepository coverageRepo,
                         SimulatorClient simulator, ObjectMapper objectMapper) {
        this.applicationRepo = applicationRepo;
        this.limitRepo = limitRepo;
        this.limitService = limitService;
        this.subLimitRepo = subLimitRepo;
        this.groupMemberRepo = groupMemberRepo;
        this.coverageRepo = coverageRepo;
        this.simulator = simulator;
        this.objectMapper = objectMapper;
    }

    public record SubLimitItem(String productId, BigDecimal subLimit) {
    }

    // ------------------------------------------------------------------ 申请

    @Transactional
    public CreditApplicationOrder apply(String customerName, CreditApplicationOrder.Type type,
                                        BigDecimal requestedLimit, String targetCreditId, String groupNo,
                                        List<SubLimitItem> productSubLimits, String guaranteeOrgName,
                                        BigDecimal coverageLimit, BigDecimal coverageRatio) {
        if (type != CreditApplicationOrder.Type.INITIAL && targetCreditId == null) {
            throw new BizException(BizException.Code.LOAN_NOT_FOUND); // 调整类申请必须指向已有授信
        }
        if (type == CreditApplicationOrder.Type.INITIAL && targetCreditId != null) {
            throw new BizException(BizException.Code.PRODUCT_NOT_OPEN);
        }
        CreditApplicationOrder order = new CreditApplicationOrder();
        order.setBizOrderNo(Ids.next("CR-"));
        order.setCustomerName(customerName);
        order.setType(type);
        order.setTargetCreditId(targetCreditId);
        order.setRequestedLimit(requestedLimit);
        order.setGroupNo(groupNo);
        order.setProductSubLimitsJson(writeJson(productSubLimits));
        order.setGuaranteeOrgName(guaranteeOrgName);
        order.setGuaranteeCoverageLimit(coverageLimit);
        order.setGuaranteeCoverageRatio(coverageRatio);
        order.setStatus(CreditApplicationOrder.Status.PROCESSING);
        order.setCreatedAt(Ids.now());
        order.setUpdatedAt(Ids.now());
        applicationRepo.save(order);
        submitApproval(order);
        return order;
    }

    public void submitApproval(CreditApplicationOrder order) {
        try {
            SimulatorClient.PaymentSubmission sub = simulator.submitApproval(
                    order.getBizOrderNo(), order.getCustomerName(), order.getRequestedLimit());
            order.setApprovalExtSerialNo(sub.extSerialNo());
            order.setUpdatedAt(Ids.now());
            if ("SUCCESS".equals(sub.status())) {
                onApprovalResult(order, "APPROVED", null);
            } else if ("REJECTED".equals(sub.status())) {
                onApprovalResult(order, "REJECTED", null);
            }
        } catch (Exception e) {
            log.warn("审批提交失败，等待补偿重试: {} {}", order.getBizOrderNo(), e.getMessage());
        }
    }

    /**
     * 审批结果落申请单（回调与查单共用）。幂等：已终态的申请单收到重复结果直接忽略。
     * approvedLimit 为 null 时取申请额度（同步批准）；批准额度可能低于申请额度。
     */
    @Transactional
    public void onApprovalResult(CreditApplicationOrder order, String result, BigDecimal approvedLimit) {
        if (order.terminal()) {
            return;
        }
        order.setUpdatedAt(Ids.now());
        if ("APPROVED".equals(result)) {
            BigDecimal effective = approvedLimit == null ? order.getRequestedLimit() : approvedLimit;
            order.setApprovedLimit(effective);
            order.setStatus(CreditApplicationOrder.Status.APPROVED);
            effectuate(order);
        } else {
            order.setStatus(CreditApplicationOrder.Status.REJECTED);
        }
    }

    /** 审批通过后的生效：INITIAL 建授信＋各层配置；INCREASE/DECREASE/RENEWAL 调整总授信（降额保留占用）。 */
    @Transactional
    public void effectuate(CreditApplicationOrder order) {
        BigDecimal limitAmount = order.getApprovedLimit();
        switch (order.getType()) {
            case INITIAL -> {
                CreditLimit limit = new CreditLimit();
                String creditId = Ids.next("CR-");
                limit.setCreditId(creditId);
                limit.setCustomerName(order.getCustomerName());
                limit.setTotalLimit(limitAmount);
                limit.setOccupied(BigDecimal.ZERO);
                limit.setPreOccupied(BigDecimal.ZERO);
                limit.setFrozen(false);
                limit.setRestricted(false);
                limitRepo.save(limit);
                order.setCreatedCreditId(creditId);
                applyLayers(order, creditId);
            }
            case LIMIT_INCREASE, RENEWAL -> {
                CreditLimit limit = requireCredit(order.getTargetCreditId());
                limit.setTotalLimit(limitAmount);
                limit.setRestricted(limit.getOccupied().add(limit.getPreOccupied()).compareTo(limitAmount) > 0);
                applyLayers(order, limit.getCreditId());
            }
            case LIMIT_DECREASE -> {
                CreditLimit limit = requireCredit(order.getTargetCreditId());
                limit.setTotalLimit(limitAmount);
                // 降额规则：占用高于新上限时保留实际占用、限制新增提款，不改已有债务
                limit.setRestricted(limit.getOccupied().add(limit.getPreOccupied()).compareTo(limitAmount) > 0);
            }
        }
    }

    private void applyLayers(CreditApplicationOrder order, String creditId) {
        if (order.getGroupNo() != null && limitService.findGroupOf(creditId).isEmpty()) {
            GroupMember member = new GroupMember();
            member.setMemberId(Ids.next("GM-"));
            member.setGroupNo(order.getGroupNo());
            member.setCreditId(creditId);
            groupMemberRepo.save(member);
        }
        for (SubLimitItem item : readSubLimits(order)) {
            if (limitService.findSubLimit(creditId, item.productId()).isEmpty()) {
                ProductSubLimit sub = new ProductSubLimit();
                sub.setSubLimitId(Ids.next("SL-"));
                sub.setCreditId(creditId);
                sub.setProductId(item.productId());
                sub.setSubLimit(item.subLimit());
                sub.setOccupied(BigDecimal.ZERO);
                sub.setPreOccupied(BigDecimal.ZERO);
                subLimitRepo.save(sub);
            }
        }
        if (order.getGuaranteeOrgName() != null && order.getGuaranteeCoverageLimit() != null
                && limitService.findCoverage(creditId).isEmpty()) {
            GuaranteeCoverage coverage = new GuaranteeCoverage();
            coverage.setCoverageId(Ids.next("GC-"));
            coverage.setCreditId(creditId);
            coverage.setOrgName(order.getGuaranteeOrgName());
            coverage.setCoverageLimit(order.getGuaranteeCoverageLimit());
            coverage.setOccupied(BigDecimal.ZERO);
            coverage.setPreOccupied(BigDecimal.ZERO);
            coverage.setCoverageRatio(order.getGuaranteeCoverageRatio());
            coverageRepo.save(coverage);
        }
    }

    // ------------------------------------------------------------------ 运营操作

    @Transactional
    public void freeze(String creditId, String reason) {
        CreditLimit limit = requireCredit(creditId);
        limit.setFrozen(true);
        log.info("授信冻结: {} 原因: {}", creditId, reason);
    }

    @Transactional
    public void unfreeze(String creditId, String reason) {
        CreditLimit limit = requireCredit(creditId);
        limit.setFrozen(false);
        log.info("授信解冻: {} 原因: {}", creditId, reason);
    }

    /** 查单收敛（补偿任务用）：审批受理超时后主动查审批结论。 */
    @Transactional
    public void queryAndSettle(CreditApplicationOrder order) {
        SimulatorClient.ExternalStatus status = simulator.query("APPROVAL", order.getApprovalExtSerialNo());
        if ("APPROVED".equals(status.result()) || "REJECTED".equals(status.result())) {
            onApprovalResult(order, status.result(), status.approvedLimit());
        }
    }

    public Map<String, Object> detail(String bizOrderNo) {
        CreditApplicationOrder order = applicationRepo.findById(bizOrderNo).orElseThrow();
        String creditId = order.getCreatedCreditId() != null
                ? order.getCreatedCreditId()
                : (order.getTargetCreditId() == null ? "" : order.getTargetCreditId());
        return Map.of("bizOrderNo", order.getBizOrderNo(), "status", order.getStatus().name(),
                "type", order.getType().name(), "requestedLimit", order.getRequestedLimit(),
                "approvedLimit", order.getApprovedLimit() == null ? "" : order.getApprovedLimit(),
                "creditId", creditId);
    }

    private CreditLimit requireCredit(String creditId) {
        return limitRepo.findById(creditId).orElseThrow(() -> new BizException(BizException.Code.LOAN_NOT_FOUND));
    }

    private List<SubLimitItem> readSubLimits(CreditApplicationOrder order) {
        try {
            return objectMapper.readValue(order.getProductSubLimitsJson(),
                    objectMapper.getTypeFactory().constructCollectionType(List.class, SubLimitItem.class));
        } catch (Exception e) {
            return List.of();
        }
    }

    private String writeJson(Object value) {
        try {
            return objectMapper.writeValueAsString(value);
        } catch (Exception e) {
            return "[]";
        }
    }
}

