package com.rsd.simulator;

import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;
import java.util.Map;

/** 中台回调投递客户端。 */
@Component
public class CallbackClient {

    private final SimulatorProps props;
    private final RestClient http;

    public CallbackClient(SimulatorProps props) {
        this.props = props;
        this.http = RestClient.builder()
                .defaultHeader(HttpHeaders.CONTENT_TYPE, MediaType.APPLICATION_JSON_VALUE)
                .build();
    }

    /** @return 回调是否被中台成功接收；审批类回调的 result 为 APPROVED/REJECTED 并附带批准额度。 */
    public boolean deliver(ExtTransaction tx, String result, String finishedAt) {
        try {
            Map<String, Object> body = new java.util.HashMap<>();
            body.put("type", tx.getKind().name());
            body.put("extSerialNo", tx.getExtSerialNo());
            body.put("bizOrderNo", tx.getBizOrderNo());
            body.put("result", result);
            body.put("finishedAt", finishedAt);
            if (tx.getKind() == ExtTransaction.Kind.APPROVAL && tx.getResultAmount() != null) {
                body.put("approvedLimit", tx.getResultAmount());
            }
            Map<String, Object> resp = http.post().uri(props.middleCallbackUrl())
                    .body(body)
                    .retrieve().body(Map.class);
            return Boolean.TRUE.equals(resp == null ? null : resp.get("received"));
        } catch (Exception e) {
            return false;
        }
    }
}

